<script setup lang="ts">
import type { RentalRequest } from '../types/domain'
defineProps<{ requests: RentalRequest[]; loading: boolean; updatingId: string }>()
const emit = defineEmits<{ refresh: []; update: [item: RentalRequest, status: string] }>()
const formatTime = (value: string) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '-'
</script>

<template>
  <section class="page-header"><div><span>业务管理</span><h1>租客需求</h1></div><el-button :loading="loading" @click="emit('refresh')">刷新数据</el-button></section>
  <div class="stats-grid list-stats"><section class="surface compact-stat"><span>需求总数</span><strong>{{ requests.length }}</strong></section><section class="surface compact-stat"><span>预约房源</span><strong>{{ requests.filter(item => item.requestType === 'appointment').length }}</strong></section><section class="surface compact-stat"><span>自主找房</span><strong>{{ requests.filter(item => item.requestType === 'general').length }}</strong></section></div>
  <section class="surface table-panel"><div class="table-heading"><div><h2>需求记录</h2><p>优先联系新提交的用户，并按预算与区域推荐房源</p></div></div><el-table :data="requests" empty-text="暂无租客需求"><el-table-column label="类型" width="130"><template #default="scope"><el-tag :type="scope.row.requestType === 'appointment' ? 'warning' : 'success'">{{ scope.row.requestType === 'appointment' ? '预约看房' : scope.row.requestType === 'area_subscription' ? '片区新房预约' : '帮我找房' }}</el-tag></template></el-table-column><el-table-column prop="phone" label="联系电话" min-width="145"><template #default="scope">{{ scope.row.phone || '待绑定' }}</template></el-table-column><el-table-column label="地区与户型" min-width="170"><template #default="scope">{{ scope.row.location || '未指定地区' }}<br/><span class="muted-table-text">{{ scope.row.layout || '户型不限' }}</span></template></el-table-column><el-table-column label="月租预算" min-width="130"><template #default="scope">{{ scope.row.budgetMin || 0 }}–{{ scope.row.budgetMax || '不限' }} 元</template></el-table-column><el-table-column label="补充要求" min-width="180"><template #default="scope"><span>{{ scope.row.note || '—' }}</span><small v-if="scope.row.followUpNote" class="muted-table-text">跟进：{{ scope.row.followUpNote }}</small></template></el-table-column><el-table-column label="跟进" min-width="220"><template #default="scope"><el-select v-model="scope.row.status" size="small" :loading="updatingId === scope.row.id" @change="emit('update', scope.row, scope.row.status)"><el-option label="待处理" value="new"/><el-option label="已联系" value="contacted"/><el-option label="已匹配" value="matched"/><el-option label="已完成" value="completed"/><el-option label="已关闭" value="closed"/></el-select><el-input v-model.trim="scope.row.followUpNote" size="small" maxlength="100" placeholder="跟进备注" @keyup.enter="emit('update', scope.row, scope.row.status)"/></template></el-table-column><el-table-column label="提交时间" min-width="165"><template #default="scope">{{ formatTime(scope.row.createdAt) }}</template></el-table-column></el-table></section>
</template>
